<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class mpackingmaterial extends CI_Controller {    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY . "mpackingmaterialmodel");        $this->load->helper('xssclean');        $this->limit = LIMITPERPAGE;        fnIfCheckUserLoggedIn();        $ArrUserLoggedInfo = fnGetUserLoggedInfo('1');        $this->companyid = $ArrUserLoggedInfo['companyid'];        $this->userid = $ArrUserLoggedInfo['id'];    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId = base64_decode(urldecode($this->uri->segment(4)));        $ArrData['Edit'] = $this->uri->segment(5);        if (is_numeric($VarId)) {            $ArrResults = $this->mpackingmaterialmodel->fnGetPackingMaterialInfo('', '', $VarId, $this->companyid);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY . 'addeditpackingmaterial', $ArrData);    }    public function updatePackingMaterialInfo() {        $ArrResult = array();        $VarPackingMaterialName = xssclean($this->input->post('pn'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarPackingMaterialName <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $this->companyid,                'packingmaterialname' => $VarPackingMaterialName, 'status' => $VarStatus,                'updatedby' => $this->userid, 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->mpackingmaterialmodel->savePackingMaterialInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input';        }        echo json_encode($ArrResult);    }    public function managepackingmaterial() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarPackingMaterialName = xssclean($this->input->post('pn'));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $ArrDbCols = array('pn.packingmaterialname', 'pn.status', 'u.contactname', 'pn.dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'mpackingmaterial/managepackingmaterial/';            $config['total_rows'] = $this->mpackingmaterialmodel->fnCountPackingMaterial($VarPackingMaterialName, $VarStatus);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "pn.dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrPackingMaterialList = $this->mpackingmaterialmodel->fnListPackingMaterial($VarPackingMaterialName, $VarStatus, $this->limit, $offset, $sortby, $sortorder)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('PackingMaterial');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrPackingMaterialList as $ObjUnit) {                $ArrFnlList[$i]['id'] = $ObjUnit->id;                $ArrFnlList[$i]['n'] = $ObjUnit->packingmaterialname;                $ArrFnlList[$i]['ub'] = $ObjUnit->contactname;                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjUnit->status];                $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjUnit->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managepackingmaterial');        }    }    function changemStatus() {        $VarActDeactOption = xssclean($this->input->post('actDeact'));        $VarCid = xssclean($this->input->post('cid'));        if ($VarActDeactOption <> '' && $VarCid <> '') {            $this->mpackingmaterialmodel->fnChangeComStat($VarCid, $VarActDeactOption);        }        echo json_encode(array('errcode' => 1));        die;    }}